/** static void SpriteCB_ChooseBoxArrow(struct Sprite *sprite) */
export function SpriteCB_ChooseBoxArrow(...args: any[]): any {
  if (++sprite.data[1] > 3)
      {
          sprite.data[1] = 0;
          sprite.x2 += sprite.data[0];
          if (++sprite.data[2] > 5)
          {
              sprite.data[2] = 0;
              sprite.x2 = 0;
          }
      }
}

