      LZ77UnCompWram(sDisplayMenu_Tilemap, sStorage.displayMenuTilemapBuffer);
      SetBgTilemapBuffer(1, sStorage.displayMenuTilemapBuffer);
      ShowBg(1);
      ScheduleBgCopyTilemapToVram(1);
