/** static void CreateWaveformSprites(void) */
export function CreateWaveformSprites(): any {
  let i: any = null;
      let sheet: any = sSpriteSheet_Waveform;

      LoadSpriteSheet(sheet);
      for (i = 0; i < ARRAY_COUNT(sStorage.waveformSprites); i++)
      {
          let spriteId = CreateSprite(sSpriteTemplate_Waveform, i * 63 + 8, 9, 2);
          sStorage.waveformSprites[i] = gSprites[spriteId];
      }
}

