/** static bool8 DoShowPartyMenu(void) */
export function DoShowPartyMenu(): any {
  switch (sStorage.showPartyMenuState)
      {
      case 0:
          if (!ShowPartyMenu())
          {
              SetCursorInParty();
              sStorage.showPartyMenuState++;
          }
          break;
      case 1:
          if (!UpdateCursorPos())
          {
              if (sStorage.setMosaic)
                  StartDisplayMonMosaicEffect();
              sStorage.showPartyMenuState++;
          }
          break;
      case 2:
          return FALSE;
      }
      return TRUE;
}

